def isHappy(self, n: int) -> bool:
    def next_val(x: int) -> int:
        total = 0
        while x > 0:
            d = x % 10
            total += d * d
            x //= 10
        return total

    seen: set[int] = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = next_val(n)
    return n == 1

